import{_ as r,C as a,o,c as s,a2 as e,E as l}from"./chunks/framework.kOe0DhAP.js";const m=JSON.parse('{"title":"核心交易流程","description":"用“部分成交后撤单”的同一个案例串联资金与订单。","frontmatter":{"title":"核心交易流程","description":"用“部分成交后撤单”的同一个案例串联资金与订单。"},"headers":[],"relativePath":"spot/flows.md","filePath":"spot/flows.md"}'),n={name:"spot/flows.md"};function h(_,t,p,c,T,g){const i=a("Flow"),d=a("SpotLedger");return o(),s("div",null,[t[0]||(t[0]=e('<div class="doc-eyebrow">现货手册 / TGEX KNOWLEDGE BASE</div><h1 id="核心交易流程" tabindex="-1">核心交易流程 <a class="header-anchor" href="#核心交易流程" aria-label="Permalink to &quot;核心交易流程&quot;">​</a></h1><div class="doc-lead">用“部分成交后撤单”的同一个案例串联资金与订单。</div><h2 id="complete" tabindex="-1">完整交易流程 <a class="header-anchor" href="#complete" aria-label="Permalink to &quot;完整交易流程 {#complete}&quot;">​</a></h2>',4)),l(i,{steps:["提交买单","校验并占用资金","进入撮合","部分成交与结算","撤销剩余订单","释放未使用资金"]}),t[1]||(t[1]=e('<p>假设用户 A 有 1,000 USDT，以 60,000 USDT 的限价买入 0.01 BTC；对手只提供 0.006 BTC，随后用户撤销剩余部分。先忽略费用并假设成交价等于限价。</p><table tabindex="0"><thead><tr><th>阶段</th><th style="text-align:right;">A 可用 USDT</th><th style="text-align:right;">A 冻结 USDT</th><th style="text-align:right;">A 新增 BTC</th><th>订单</th></tr></thead><tbody><tr><td>初始</td><td style="text-align:right;">1,000</td><td style="text-align:right;">0</td><td style="text-align:right;">0</td><td>尚未提交</td></tr><tr><td>下单占用 600</td><td style="text-align:right;">400</td><td style="text-align:right;">600</td><td style="text-align:right;">0</td><td>未成交</td></tr><tr><td>成交 0.006 BTC</td><td style="text-align:right;">400</td><td style="text-align:right;">240</td><td style="text-align:right;">0.006</td><td>部分成交</td></tr><tr><td>撤销剩余 0.004 BTC</td><td style="text-align:right;">640</td><td style="text-align:right;">0</td><td style="text-align:right;">0.006</td><td>已撤销</td></tr></tbody></table><p>最终实际支出 360 USDT，撤单不会取消这笔已完成的成交。资金变化可以在下方交互演算中检查。</p>',3)),l(d),t[2]||(t[2]=e('<h2 id="place" tabindex="-1">下单与资金冻结 <a class="header-anchor" href="#place" aria-label="Permalink to &quot;下单与资金冻结 {#place}&quot;">​</a></h2><ol><li>校验用户、商户、交易对和交易状态。</li><li>检查订单类型、价格、数量、精度与限额。</li><li>计算并占用买单所需计价币或卖单所需基础币。</li><li>建立可追踪的委托关系并交给交易处理链。</li><li>返回已确认的受理结果，客户端查询后续状态。</li></ol><p>顺序图为业务抽象，创建订单和资金动作的事务边界需要按实际服务核对。请求超时不能直接认为订单失败，更不能直接重复冻结。</p><h2 id="match" tabindex="-1">撮合与成交 <a class="header-anchor" href="#match" aria-label="Permalink to &quot;撮合与成交 {#match}&quot;">​</a></h2><p>撮合引擎检查最优对手价格。若有符合价格条件的订单，成交数量取双方剩余数量中的较小值；继续处理剩余量，直到价格不再满足或订单全部成交。</p><p>每笔成交需要唯一标识，并关联双方订单、交易对、价格和数量。未成交剩余部分是否留在订单簿，由订单类型与实际产品规则决定。</p><h2 id="settle" tabindex="-1">成交结算 <a class="header-anchor" href="#settle" aria-label="Permalink to &quot;成交结算 {#settle}&quot;">​</a></h2><p>以 0.006 BTC、60,000 USDT 成交为例，金额为 360 USDT。买方减少对应占用并增加 BTC，卖方减少 BTC 占用并增加 USDT；手续费按配置单独计算并记录。</p><p>若成交价优于买入限价，还需区分实际扣款与原预占金额，确保多占用部分最终可解释并正确释放。</p><h2 id="cancel" tabindex="-1">撤单与资金解冻 <a class="header-anchor" href="#cancel" aria-label="Permalink to &quot;撤单与资金解冻 {#cancel}&quot;">​</a></h2><ol><li>校验订单归属与可撤销状态。</li><li>将撤销请求交给权威交易处理链。</li><li>确定撤销生效前已成交的数量。</li><li>终止剩余数量，按剩余占用释放资金。</li><li>更新订单、资金记录与用户通知。</li></ol><p>撤单与成交可能竞争同一个剩余量。不能在客户端点击撤单时就直接按旧快照解冻，也不能撤销已经成交的部分。</p>',12))])}const S=r(n,[["render",h]]);export{m as __pageData,S as default};
